    current_segment = ""
    open_count = 0

    for char in paren_string:
        if char == '(':
            open_count += 1
            if open_count == 1:
                current_segment += char
        elif char == ')':
            open_count -= 1
            if open_count == 0:
                current_segment += char
                result.append(current_segment)
